import{describe,it,expect,beforeEach}from"vitest";describe("SPA Router Unit Tests",()=>{beforeEach(()=>{document.body.innerHTML='<div id="app-root"></div>'}),it("initializes route state correctly",()=>{const e="/",t=["/"];new Map;expect(e).toBe("/"),expect(t).toHaveLength(1)}),it("handles route caching and fallback rendering",()=>{const e=new Map;e.set("/frontend/states/delhi","<h1>Delhi Explorer</h1>"),expect(e.has("/frontend/states/delhi")).toBe(!0),expect(e.get("/frontend/states/delhi")).toContain("Delhi Explorer"),expect(e.has("/404")).toBe(!1)}),it("escapes HTML strings safely for error views",()=>{var e;expect((e='<script>alert("xss")<\/script>',String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"))).toBe("&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;")})});